46:   /* ------------------------------------------------ audio: crude synth */
47:   const Audio = (function () {
48:     let ctx = null;
49:     const on = () => !!ctx;
50:     function boot() {
51:       if (ctx) return;
52:       try { ctx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) {}
53:     }
54:     function noise(dur, gainV, filterHz, decay) {
55:       if (!ctx) return;
56:       const b = ctx.createBuffer(1, ctx.sampleRate * dur, ctx.sampleRate);
57:       const d = b.getChannelData(0);
58:       for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / d.length, decay || 1);
59:       const src = ctx.createBufferSource(); src.buffer = b;
60:       const g = ctx.createGain(); g.gain.value = gainV;
61:       const f = ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = filterHz || 900; f.Q.value = .6;
62:       src.connect(f); f.connect(g); g.connect(ctx.destination);
63:       src.start();
64:     }
65:     function tone(freq, dur, type, gainV, slideTo) {
66:       if (!ctx) return;
67:       const o = ctx.createOscillator(), g = ctx.createGain();
68:       o.type = type || 'sawtooth'; o.frequency.value = freq;
69:       if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, ctx.currentTime + dur);
70:       g.gain.value = gainV || .08;
71:       g.gain.exponentialRampToValueAtTime(.001, ctx.currentTime + dur);
72:       o.connect(g); g.connect(ctx.destination);
73:       o.start(); o.stop(ctx.currentTime + dur + .05);
74:     }
75:     return {
76:       boot, on,
77:       stinger: () => { tone(160, .8, 'sawtooth', .07, 55); tone(161.7, .8, 'square', .04, 55.4); noise(.5, .05, 300, 2); },
78:       shutter: () => { noise(.07, .5, 3200, 2); noise(.05, .3, 900, 2); },
79:       cheer: () => { noise(1.4, .22, 700, 1.2); noise(1.2, .18, 1400, 1.4); },
80:       boo: () => { tone(90, 1.1, 'sawtooth', .05, 41); noise(.9, .12, 240, 1.4); },
81:       click: () => { noise(.04, .25, 2400, 2); },
82:       thud: () => { tone(70, .24, 'sine', .2, 38); noise(.12, .25, 180, 2); },
83:       buzz: () => { tone(55, .6, 'sawtooth', .028, 55); tone(110, .6, 'sine', .02, 108); },
84:     };
85:   })();
