87:   /* ------------------------------------------------ camera director */
88:   const Cam = {
89:     mode: 'title', subject: null, shake: 0,
90:     desired: new THREE.Vector3(),
91:     look: new THREE.Vector3(),
92:     titleA: 0,
93:     update(dt, t) {
94:       const subj = this.subject;
95:       switch (this.mode) {
96:         case 'title':
97:           this.titleA += dt * .12;
98:           this.desired.set(Math.sin(this.titleA) * 7, 2.6 + Math.sin(t * .3), -2 + Math.cos(this.titleA) * 5);
99:           this.look.set(0, 1.6, -2);
100:           break;
101:         case 'announce':
102:           this.desired.set(0, 2.8, 7.5);
103:           this.look.set(0, 1.2, -4);
104:           break;
105:         case 'dress': {
106:           if (!subj) break;
107:           const p = subj.group.position;
108:           this.desired.set(p.x + Math.sin(t * .22) * 2.1, 1.55, p.z + 2.6 + Math.cos(t * .22) * .9);
109:           this.look.set(p.x, 1.25, p.z + .2);
110:           break;
111:         }
112:         case 'walk': {
113:           if (!subj) break;
114:           const p = subj.group.position;
115:           const wob = Math.sin(t * 1.7) * .25;
116:           this.desired.set(p.x + 1.15 + wob, 1.45, RC.lerp(p.z + 4.6, 9.2, RC.clamp((p.z + 11) / 19, 0, .55)));
117:           this.look.set(p.x * .7, 1.28, p.z + .5);
118:           break;
119:         }
120:         case 'pose': {
121:           if (!subj) break;
122:           const p = subj.group.position;
123:           this.poseT = (this.poseT || 0) + dt;
124:           const push = RC.clamp(this.poseT * .12, 0, 1);
125:           this.desired.set(p.x + 1.0 - push * 1.6, 1.35 - push * .25, p.z + 3.4 - push * 1.1);
126:           this.look.set(p.x * .5, 1.32, p.z + .3);
127:           break;
128:         }
129:         case 'jury':
130:           this.desired.set(1.8, 2.2, 9.6);
131:           this.look.set(.4, 1.55, 12.6);
132:           break;
133:         case 'finale': {
134:           if (!subj) break;
135:           this.finaleA = (this.finaleA || 0) + dt * .35;
136:           const p = subj.group.position;
137:           this.desired.set(p.x + Math.sin(this.finaleA) * 3.2, 2.1, p.z + 3.4 + Math.cos(this.finaleA) * 2.2);
138:           this.look.set(p.x, 1.5, p.z);
139:           break;
140:         }
141:       }
142:       const k = 1 - Math.exp(-dt * 3.2);
143:       camera.position.lerp(this.desired, k);
144:       camera.lookAt(this.look);
145:       if (this.shake > 0) {
146:         this.shake -= dt;
147:         camera.position.x += (Math.random() - .5) * .05;
148:         camera.position.y += (Math.random() - .5) * .05;
149:       }
150:     },
151:     set(mode, subject) {
152:       if (this.mode === 'pose' && mode !== 'pose') this.poseT = 0;
153:       this.mode = mode; this.subject = subject || null;
154:       if (mode === 'pose') this.poseT = 0;
155:       if (mode === 'finale') this.finaleA = 0;
156:     },
157:     kick(s) { this.shake = s; }
158:   };
