240:     gem.position.set(0, .04, .15); g.add(gem);
241:     g.position.set(chr.bones.head.position.x, 1.2, 0);
242:     g.position.set(0, 1.6, 0);
243:     chr.anchors.head.add(g);
244:     g.position.set(0, 2.2, 0);
245:     RC.Tweens.add({
246:       dur: 1.3, onUpdate: k => {
