330:   async function walkIn(chr, from, to, dur) {
331:     RC.resetRatPose(chr);
332:     chr.anim.mode = 'walk'; chr.anim.speed = .75;
333:     chr.group.position.set(from.x, from.y, from.z);
334:     const fx = from.x, fz = from.z;
335:     await RC.Tweens.add({
336:       dur,
337:       onUpdate: k => { chr.group.position.set(fx, from.y, RC.lerp(fz, to.z, k)); },
338:     });
339:   }
340:   async function walkOut(chr, target, dur) {
341:     RC.resetRatPose(chr);
342:     chr.anim.mode = 'walk'; chr.anim.speed = .9;
343:     const fx = chr.group.position.x, fz = chr.group.position.z;
344:     await RC.Tweens.add({
345:       dur,
346:       onUpdate: k => { chr.group.position.set(RC.lerp(fx, target.x, k), target.y, RC.lerp(fz, target.z, k)); },
347:     });
348:   }
