387:   async function judgeContestant(c, theme) {
388:     const marks = RC.JURY.map(j => RC.judgeOutfit(c.outfitItems, theme, j));
389:     const totalMarks = marks.reduce((a, b) => a + b, 0) / marks.length;
390:     c.roundScore = totalMarks * 2;   // scale to 20 per round
391:     return { marks, totalMarks };
