394:   async function showtimeRound(theme) {
395:     const order = RC.shuffled(contestants);
396:     for (const c of order) {
397:       RC.resetRatPose(c.chr);
398:       spotlightOn(c);
399:       Cam.set('walk', c.chr);
400:       UI.banner('NOW STALKING THE RUNWAY', c.name, c.isPlayer ? '(THAT IS YOUR PATHETIC SELF)' : RC.pick(['fresh from the bin', 'greased and trembling', 'uncertain of itself', 'here for chaos, stays for the flies', 'professionally filthy']));
401:       c.chr.anim.mode = 'idle';
402:       await RC.wait(.85);
403:       await walkIn(c.chr, { x: 0, y: .12, z: RUNWAY_Z0 }, { z: POSE_Z }, 3.4);
404:       /* pose + paparazzi */
405:       Cam.set('pose', c.chr);
406:       RC.resetRatPose(c.chr);
407:       c.chr.anim.mode = 'pose';
408:       c.chr.anim.speed = 0;
409:       await RC.wait(.85);
410:       flashBurst(c.chr.group.position, true);
411:       Cam.kick(.15);
412:       await RC.wait(1.15);
413:       /* jury verdicts */
414:       Cam.set('jury');
415:       const { marks, totalMarks } = await judgeContestant(c, theme);
416:       for (let j = 0; j < RC.JURY.length; j++) {
417:         const jry = RC.JURY[j];
418:         UI.quote(jry.name, jry.role, marks[j], RC.jurorLine(jry, marks[j]));
419:         /* speaking bob */
420:         const jr = juryRats[j];
421:         Audio.buzz();
422:         RC.Tweens.add({
423:           dur: .5, onUpdate: k => {
424:             jr.chr.refs.upR.rotation.x = -2.2 + Math.sin(k * Math.PI) * .4;
425:             jr.chr.refs.elR.rotation.x = -1.1;
426:           },
427:         });
428:         await RC.wait(2.0);
429:       }
430:       UI.quoteHide();
431:       c.score += c.roundScore;
432:       c._lastRoundScore = c.roundScore;
433:       UI.scoreboard(sortedStandings());
434:       UI.outfitTags(c.outfitItems);
435:       (marks[0] + marks[1] + marks[2] > 16.5 ? Audio.cheer : Audio.boo)();
436:       await RC.wait(1.1);
437:       /* exit stage right */
438:       Cam.set('walk', c.chr);
439:       RC.resetRatPose(c.chr);
440:       c.chr.anim.mode = 'walk';
441:       await walkOut(c.chr, { x: OFF_X, y: .12, z: OFF_Z }, 1.6);
442:       c.chr.group.visible = false;
443:       await RC.wait(.35);
444:       UI.outfitTags([]);
