459:   async function startMatch() {
460:     if (busy) return;
461:     busy = true;
462:     try {
463:       /* reset everything */
464:       contestants.forEach(c => { c.score = 0; });
465:       newGameKeepPlayer();
466:       const themes = RC.shuffled(RC.THEMES).slice(0, ROUNDS);
467:       Cam.set('title');
468:       await RC.wait(1.0);
469:       for (let r = 0; r < themes.length; r++) {
470:         const theme = themes[r];
471:         UI.letterbox(true);
472:         Cam.set('announce');
473:         Audio.stinger();
474:         UI.roundInfo(r + 1, ROUNDS, theme.name, theme.sub);
475:         UI.banner(`ROUND ${r + 1} — THE THEME IS`, theme.name, '"' + theme.sub + '"');
476:         await RC.wait(2.4);
477:         /* jury announcer */
478:         Cam.set('jury');
479:         const jr0 = RC.JURY.find(j => theme.quote[0].includes(j.name.split(' ')[0])) || RC.JURY[0];
480:         UI.quote(jr0.name, jr0.role + ' / RINGMASTER', null, theme.quote[1]);
481:         Audio.buzz();
482:         await RC.wait(2.2);
483:         UI.quoteHide();
484:         UI.letterbox(false);
485: 
486:         /* pick the 5 random categories */
487:         const cats = RC.shuffled(RC.CATEGORIES).slice(0, 5);
488:         const playerC = contestants.find(c => c.isPlayer);
