24:     add(t) {
25:       t = Object.assign({ t: 0, dur: 1, ease: RC.smooth, onUpdate: () => {}, resolve: null }, t);
26:       this.list.push(t);
27:       return new Promise(res => { t.resolve = res; });
28:     },
29:     update(dt) {
30:       let i = 0;
31:       while (i < this.list.length) {
32:         const tw = this.list[i];
33:         tw.t += dt;
34:         const k = RC.clamp(tw.t / tw.dur, 0, 1);
35:         try { tw.onUpdate(tw.ease(k), k); } catch (e) { console.error(e); }
