  const ear = opt('ears', st.ears).apply || {};
  const snout = opt('snout', st.snout).apply || {};
  const teeth = opt('teeth', st.teeth).apply || {};
  Object.assign(spec, eye, ear, snout, teeth);
  /* if ear opt gave no size, default 1 */
  spec.earSize = spec.earSize || 1;
  if (FURS.find(f => f.id === st.fur).baldPatches) {
    spec.baldPatches = (spec.baldPatches || 0) + FURS.find(f => f.id === st.fur).baldPatches;
  }
  /* gross details: combine freely */
  (st.details || []).forEach(id => {
    const d = DETAILS.find(x => x.id === id);
    if (d) Object.assign(spec, d.apply);
  });
  /* fur option adds its own bald patches only when not already huge */
  return spec;
}

