/* ==================== STEP 2 · FLESH ATELIER (creator) ==================== */
#creator {
  position: absolute; inset: 0; z-index: 21;
  pointer-events: none;
  font-family: 'Special Elite', 'Courier New', monospace;
}
/* the canvas below stays fully interactive for orbiting the model */
#creator, #creator * { pointer-events: none; }
#creatorHead, .crPanel, #creatorFoot, #zoomBtns { pointer-events: auto; }

#creatorHead {
  position: absolute; top: 0; left: 0; right: 0;
  display: flex; justify-content: space-between; align-items: flex-start; gap: 16px;
  padding: 14px 20px 20px;
  background: linear-gradient(rgba(6,5,4,.92), rgba(6,5,4,.55) 70%, transparent);
}
.crKick { font-size: 11px; letter-spacing: 4px; color: #6a3020; color: var(--blood); opacity: .85; }
.crTitle {
  font-family: 'Rubik Glitch', 'Bebas Neue', Impact, sans-serif;
  font-size: clamp(26px, 4.4vw, 52px); line-height: 1;
  color: var(--bone);
  text-shadow: 3px 3px 0 var(--blood), -2px -2px 0 #000, 0 0 34px rgba(255,42,74,.3);
  transform: rotate(-1.2deg);
}
.crRecipe { margin-top: 8px; font-size: 12px; letter-spacing: 2px; color: var(--acid); text-transform: uppercase; }
.crRecipe::before { content: '» INTAKE SUMMARY: '; color: #9a8f7a; }

#viewBox { text-align: right; }
.vbtn {
  font-family: 'Bebas Neue', Impact, sans-serif; font-size: 15px; letter-spacing: 2px;
  min-width: 74px; padding: 8px 12px; cursor: pointer;
  color: #9a8f7a; background: #16130f; border: 1px solid #2a241e;
  border-bottom: 3px solid #000;
}
.vbtn:hover { color: var(--bone); border-color: #6a5a44; }
.vbtn.active { color: #0c0c0c; background: var(--acid); border-color: var(--acid); }
#orbHint { margin-top: 8px; font-size: 10px; letter-spacing: 2px; color: #6a6056; }

.crPanel {
  position: absolute; top: 118px; bottom: 96px; width: 272px;
  overflow-y: auto; padding: 10px 12px 24px;
  background: linear-gradient(rgba(10,9,7,.88), rgba(8,7,6,.94));
  border: 1px solid #2c2620;
  box-shadow: 0 0 40px rgba(0,0,0,.65);
  scrollbar-width: thin; scrollbar-color: var(--blood) #111;
}
.crPanel::before {
  content: ''; position: sticky; display: block; top: -10px; margin: -10px -12px 10px;
  height: 14px; pointer-events: none; z-index: 1;
  background: linear-gradient(rgba(12,10,8,.95), transparent);
}
#creatorLeft { left: 14px; transform: skewX(-1.4deg); }
#creatorRight { right: 14px; width: 284px; transform: skewX(1.2deg); }

.crSec { border: 1px solid #2a241e; margin-bottom: 12px; padding: 10px 10px 8px; background: rgba(14,12,10,.72); }
.crSec h3 {
  margin: 0 0 8px; font-family: 'Bebas Neue', Impact, sans-serif;
  font-size: 15px; letter-spacing: 3px; color: var(--acid);
  border-bottom: 1px dashed #3a342a; padding-bottom: 5px;
}
.optBtn {
  display: block; width: 100%; text-align: left; margin-bottom: 6px;
  font-family: 'Special Elite', monospace; cursor: pointer;
  background: #14110e; color: var(--bone);
  border: 1px solid #2a241e; border-left: 3px solid #2a241e;
  padding: 7px 9px 8px;
  transition: border-color .1s, background .12s, transform .06s;
}
.optBtn:hover { border-color: #6a5a44; transform: translateX(2px); background: #191510; }
.optBtn.sel {
  border-color: var(--acid); background: #1a1e10;
  box-shadow: 0 0 10px rgba(157,255,42,.14), inset 0 0 14px rgba(157,255,42,.06);
}
.obName { display: block; font-family: 'Bebas Neue', Impact, sans-serif; font-size: 16px; letter-spacing: 1px; }
.obSub { display: block; font-size: 10.5px; font-style: italic; color: #8a7f6c; line-height: 1.4; margin-top: 1px; }
.optBtn.row { display: flex; align-items: center; gap: 10px; }
.optBtn.row .obName { flex: 1; }
.furChip {
  width: 30px; height: 30px; flex: 0 0 30px; display: inline-block;
  border: 2px solid #3a342a; box-shadow: inset 0 3px 8px rgba(0,0,0,.5);
}
.furChip.patchy {
  background:
    repeating-linear-gradient(38deg, #2a2624 0 7px, #cfc4b0 7px 10px, #7a4a32 10px 16px, #b09a6a 16px 20px);
  background-color: #58514a;
}
.optBtn.sel .furChip { border-color: var(--acid); }
.optBtn.mini { display: flex; justify-content: space-between; align-items: center; gap: 6px; padding: 5px 9px; }
.optBtn.mini .obName { font-size: 14px; }
.tglMark { display: none; font-size: 9px; letter-spacing: 1px; color: #0c0c0c; background: var(--acid); padding: 2px 5px; }
.optBtn.togg.sel .tglMark { display: inline-block; }

#zoomBtns {
  position: absolute; right: 310px; bottom: 108px; z-index: 22;
  display: flex; flex-direction: column; gap: 6px;
}
#zoomBtns button {
  width: 42px; height: 42px; font-size: 24px; cursor: pointer;
  font-family: 'Bebas Neue', Impact; color: var(--bone);
  background: rgba(16,13,10,.9); border: 1px solid #3a342a; border-bottom: 3px solid #000;
}
#zoomBtns button:hover { color: var(--acid); border-color: var(--acid); }
#zoomBtns button:active { transform: translateY(2px); }

#creatorFoot {
  position: absolute; left: 0; right: 0; bottom: 0;
  display: flex; align-items: stretch; gap: 12px; flex-wrap: wrap;
  padding: 14px 20px 16px;
  background: linear-gradient(transparent, rgba(6,5,4,.9) 30%, rgba(6,5,4,.97));
  border-top: 1px solid #2a241e;
}
#nameWrap { flex: 1 1 240px; min-width: 220px; display: flex; flex-direction: column; gap: 4px; }
#nameWrap label { font-size: 10px; letter-spacing: 3px; color: #9a8f7a; }
#ratName {
  width: 100%; max-width: 420px;
  font-family: 'Bebas Neue', Impact, sans-serif; font-size: 24px; letter-spacing: 2px;
  color: var(--bone); background: rgba(20,16,12,.8);
  border: 1px solid #3a322a; border-left: 4px solid var(--blood);
  padding: 8px 12px; outline: none;
  text-transform: uppercase;
}
#ratName:focus { border-color: var(--acid); border-left-color: var(--acid); box-shadow: 0 0 14px rgba(157,255,42,.15); }
#nameWrap, #creatorFoot .rbtn { pointer-events: auto; }
#btnFreak { flex: 0 1 auto; font-size: 18px; }
#btnConfirm { flex: 0 1 auto; font-size: 24px; padding: 12px 30px; }

@media (max-width: 980px) {
  .crPanel { top: 128px; bottom: 150px; width: 214px; }
  #creatorRight { width: 222px; }
  #zoomBtns { right: 240px; bottom: 168px; }
  .crTitle { font-size: clamp(22px, 5.5vw, 40px); }
  #orbHint { display: none; }
  #btnConfirm { font-size: 19px; padding: 10px 18px; }
  #btnFreak { font-size: 15px; padding: 8px 14px; }
  .obSub { display: none; }
  .optBtn.big .obSub, .optBtn.row .obSub { display: none; }
}

/* ==================== round board / finale ================= */

