const puppeteer = require('puppeteer-core');
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium', headless: 'new',
    args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=swiftshader', '--enable-unsafe-swiftshader'],
    defaultViewport: { width: 1440, height: 900 },
  });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message.split('\n')[0] + ' | ' + (e.message.split('\n')[1] || '').trim().slice(0, 90)));
  page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) errors.push('CONSOLE: ' + m.text()); });
  await page.goto('http://localhost:8419/', { waitUntil: 'load' });
  await new Promise(r => setTimeout(r, 2500));
  await page.screenshot({ path: '/tmp/opencode/shot-creator-default.png' });

  // extreme character
  await page.click('[data-gid="f"]');
  await page.click('[data-bid="mutant"]');
  await page.click('[data-fid="patchy"]');
  await page.click('[data-oid="huge"][data-fg="eyes"]');
  await page.click('[data-oid="crooked"][data-fg="teeth"]');
  await page.click('[data-oid="torn"][data-fg="ears"]');
  await page.click('[data-oid="bulbous"][data-fg="snout"]');
  for (const d of ['warts', 'pimples', 'jaw', 'nofur', 'unevenears', 'scars']) await page.click(`[data-did="${d}"]`);
  await new Promise(r => setTimeout(r, 900));
  await page.screenshot({ path: '/tmp/opencode/shot-creator-max.png' });

  // confirm: every option once + freak once, ensure no explosion
  const groups = await page.evaluate(() => {
    const gs = {};
    document.querySelectorAll('[data-fg]').forEach(b => { (gs[b.dataset.fg] = gs[b.dataset.fg] || []).push(b.dataset.oid); });
    return gs;
  });
  for (const fg of Object.keys(groups)) {
    for (const oid of groups[fg]) { await page.click(`[data-oid="${oid}"][data-fg="${fg}"]`); await new Promise(r => setTimeout(r, 120)); }
  }
  // all body types + furs once
  const bids = await page.evaluate(() => [...document.querySelectorAll('[data-bid]')].map(b => b.dataset.bid));
  for (const id of bids) { await page.click(`[data-bid="${id}"]`); await new Promise(r => setTimeout(r, 100)); }
  const fids = await page.evaluate(() => [...document.querySelectorAll('[data-fid]')].map(b => b.dataset.fid));
  for (const id of fids) { await page.click(`[data-fid="${id}"]`); await new Promise(r => setTimeout(r, 100)); }
  console.log('TOURED ALL OPTIONS');
  await page.click('#btnFreak');
  await new Promise(r => setTimeout(r, 600));
  await page.screenshot({ path: '/tmp/opencode/shot-creator-freak.png' });

  await page.evaluate(() => { document.getElementById('ratName').value = 'THESEWERSWEEPER'; });
  await page.click('#btnConfirm');
  await new Promise(r => setTimeout(r, 6500));

  // dress: pick one per category, then RE-PICK the same category to test disposal fix
  async function pickOneAndSend(retry) {
    for (let i = 0; i < 5 + (retry ? 2 : 0); i++) {
      const tabs = await page.evaluate(() => [...document.querySelectorAll('.catTab')].map(t => ({ id: t.dataset.cat, done: t.querySelector('.st').textContent === '✓' })));
      const tab = tabs.find(t => !t.done) || tabs[0];
      await page.evaluate(id => document.querySelector(`.catTab[data-cat="${id}"]`).click(), tab.id);
      await new Promise(r => setTimeout(r, 250));
      const hasCards = await page.evaluate(() => document.querySelectorAll('.itemCard').length);
      if (!hasCards) break;
      await page.evaluate(() => document.querySelectorAll('.itemCard')[0].click());
      await new Promise(r => setTimeout(r, 250));
    }
    const can = await page.evaluate(() => !document.getElementById('btnSend').disabled);
    console.log('BTN_SEND_ENABLED:', can);
    if (can) { await page.click('#btnSend'); return true; }
    return false;
  }
  const sent = await pickOneAndSend(false);
  console.log('SENT:', sent);

  // let the whole round play (walk, pose, 3 jury quotes, scoreboard)
  await new Promise(r => setTimeout(r, 32000));
  await page.screenshot({ path: '/tmp/opencode/shot-round.png' });
  const st = await page.evaluate(() => ({
    roundBoard: !document.getElementById('roundBoard').classList.contains('hidden'),
    rows: document.querySelectorAll('#roundBoardRows .fbRow').length,
    playerScore: (document.querySelector('#roundBoardRows .fbRow.you .pts') || { textContent: '?' }).textContent,
  }));
  console.log('ROUND BOARD:', JSON.stringify(st));
  console.log('ERRORS:', errors.length ? errors.slice(0, 10) : 'none');
  await browser.close();
})().catch(e => { console.error('TEST FAILED:', e); process.exit(1); });

