      window.__errs.push(String(e.message) + '\n   ' + String((e.error && e.error.stack) || '').split('\n').slice(1, 5).join('\n   '));
    });
  });
  page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) console.log('CONSOLE:', m.text().slice(0, 200)); });
  await page.goto('http://localhost:8419/', { waitUntil: 'load' });
  await new Promise(r => setTimeout(r, 2000));
  await page.click('#btnFreak');
  await new Promise(r => setTimeout(r, 400));
  await page.evaluate(() => { document.getElementById('ratName').value = 'TESTFREAK'; });
  await page.click('#btnConfirm');
  await new Promise(r => setTimeout(r, 6000));
  const errs = await page.evaluate(() => window.__errs);
  console.log(errs.length ? 'ERRS:\n' + errs.join('\n---\n') : 'no errs');
  await browser.close();
})().catch(e => { console.error('TESTFAILED', e); process.exit(1); });

