const puppeteer = require('puppeteer-core');
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium', headless: 'new',
    args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=swiftshader', '--enable-unsafe-swiftshader'],
    defaultViewport: { width: 1280, height: 800 },
  });
  const page = await browser.newPage();
  page.on('console', m => { if (m.type() === 'error' && m.text().includes('NaN')) console.log('NAN:', m.text().slice(0, 120)); });
  await page.goto('http://localhost:8419/', { waitUntil: 'load' });
  await new Promise(r => setTimeout(r, 1800));
  const check = () => page.evaluate(() => {
    const bad = [];
    (window.RC.creator.preview ? window.RC.creator.preview : null);
    const root = window.RC.creator.preview && window.RC.creator.preview.group;
    root.traverse(o => {
      if (o.geometry) {
        const p = o.geometry.attributes && o.geometry.attributes.position;
        if (p) { for (let i = 0; i < p.array.length; i++) if (!isFinite(p.array[i])) { bad.push(o.type + ':' + (o.name || '?')); break; } }
      }
      if (o.isInstancedMesh) {
        const arr = o.instanceMatrix.array;
        for (let i = 0; i < arr.length; i++) if (!isFinite(arr[i])) { bad.push('Inst:' + o.type); break; }
      }
    });
    return bad.slice(0, 6);
  });
  const first = await check();
  console.log('default preview NaN:', first.length ? first : 'none');
  const clicks = [
    ['[data-bid="skinny"]', 'body skinny'], ['[data-bid="mutant"]', 'body mutant'],
    ['[data-gid="f"]', 'female'], ['[data-fid="hairless"]', 'hairless'],
    ['[data-fid="patchy"]', 'patchy'], ['[data-oid="huge"][data-fg="eyes"]', 'huge eyes'],
    ['[data-oid="cross"][data-fg="eyes"]', 'cross'], ['[data-oid="blood"][data-fg="eyes"]', 'bloodshot'],
    ['[data-oid="missing"][data-fg="teeth"]', 'missing teeth'], ['[data-oid="rotten"][data-fg="teeth"]', 'rotten teeth'],
    ['[data-oid="crooked"][data-fg="teeth"]', 'crooked teeth'], ['[data-oid="torn"][data-fg="ears"]', 'torn ears'],
    ['[data-oid="huge"][data-fg="ears"]', 'huge ears'], ['[data-oid="bent"][data-fg="snout"]', 'bent nose'],
    ['[data-oid="bulbous"][data-fg="snout"]', 'bulbous'], ['[data-oid="long"][data-fg="snout"]', 'long snout'],
    ['[data-oid="short"][data-fg="snout"]', 'short snout'],
    ['[data-did="warts"]', 'warts'], ['[data-did="pimples"]', 'pimples'], ['[data-did="scars"]', 'scars'],
    ['[data-did="bald"]', 'bald'], ['[data-did="whiskers"]', 'whiskers'], ['[data-did="blemish"]', 'blemish'],
    ['[data-did="jaw"]', 'jaw'], ['[data-did="unevenears"]', 'uneven ears'], ['[data-did="nofur"]', 'nofur'],
  ];
  for (const [sel, label] of clicks) {
    await page.evaluate(s => { const el = document.querySelector(s); if (el) el.click(); }, sel);
    await new Promise(r => setTimeout(r, 250));
    const bad = await check();
    if (bad.length) console.log('NAN after', label, '→', bad);
  }
  console.log('BISCUIT DONE. remaining errors:', (await page.evaluate(() => window.__errs || [])).length);
  await browser.close();
})().catch(e => { console.error('TESTFAILED', e); process.exit(1); });

